Object.assign(DPIA_TRANSLATIONS,{"La configuración se guarda en tu cuenta DPIA. Guardarla no activa el agente.": ["Configuration is saved to your DPIA account. Saving it does not activate the agent.", "Konfiguracja jest zapisywana na Twoim koncie DPIA. Zapis nie aktywuje agenta.", "La configurazione viene salvata nel tuo account DPIA. Il salvataggio non attiva l’agente."], "Cargando configuración del agente…": ["Loading agent configuration…", "Ładowanie konfiguracji agenta…", "Caricamento configurazione dell’agente…"], "Iniciá sesión para guardar tu agente.": ["Sign in to save your agent.", "Zaloguj się, aby zapisać agenta.", "Accedi per salvare il tuo agente."], "Recuperar borrador local": ["Recover local draft", "Odzyskaj lokalny szkic", "Recupera bozza locale"], "Guardando configuración…": ["Saving configuration…", "Zapisywanie konfiguracji…", "Salvataggio configurazione…"], "Volver a cargar configuración": ["Reload configuration", "Wczytaj konfigurację ponownie", "Ricarica configurazione"], "No se confirmó el guardado del agente. Volvé a cargar su configuración.": ["Agent save was not confirmed. Reload its configuration.", "Zapis agenta nie został potwierdzony. Wczytaj ponownie jego konfigurację.", "Salvataggio dell’agente non confermato. Ricarica la configurazione."], "La respuesta del agente no es válida. Volvé a cargar su configuración.": ["Invalid agent response. Reload its configuration.", "Nieprawidłowa odpowiedź agenta. Wczytaj ponownie konfigurację.", "Risposta dell’agente non valida. Ricarica la configurazione."], "No se pudo cargar la configuración del agente.": ["Could not load agent configuration.", "Nie udało się wczytać konfiguracji agenta.", "Impossibile caricare la configurazione dell’agente."], "Revisá la configuración del agente.": ["Review the agent configuration.", "Sprawdź konfigurację agenta.", "Controlla la configurazione dell’agente."], "El guardado del agente requiere MySQL.": ["Agent storage requires MySQL.", "Zapis agenta wymaga MySQL.", "Il salvataggio dell’agente richiede MySQL."], "Hay varias configuraciones para esta cuenta. Revisá los datos antes de guardar.": ["There are multiple configurations for this account. Review the data before saving.", "Dla tego konta istnieje kilka konfiguracji. Sprawdź dane przed zapisem.", "Esistono più configurazioni per questo account. Controlla i dati prima di salvare."], "La configuración guardada no es compatible. Revisala antes de guardar.": ["The saved configuration is incompatible. Review it before saving.", "Zapisana konfiguracja jest niezgodna. Sprawdź ją przed zapisem.", "La configurazione salvata non è compatibile. Controllala prima di salvare."], "Este agente tiene actividad habilitada. No se modificó su configuración.": ["This agent has activity enabled. Its configuration was not changed.", "Ten agent ma włączoną aktywność. Jego konfiguracja nie została zmieniona.", "Questo agente ha attività abilitate. La configurazione non è stata modificata."], "La configuración cambió en otra pestaña. Volvé a cargarla antes de editar.": ["The configuration changed in another tab. Reload it before editing.", "Konfiguracja zmieniła się w innej karcie. Wczytaj ją ponownie przed edycją.", "La configurazione è cambiata in un’altra scheda. Ricaricala prima di modificarla."], "Solicitud de configuración no autorizada.": ["Unauthorized configuration request.", "Nieautoryzowane żądanie konfiguracji.", "Richiesta di configurazione non autorizzata."], "No se pudo verificar el catálogo del agente. Reintentá.": ["Could not verify the agent catalog. Try again.", "Nie udało się zweryfikować katalogu agenta. Spróbuj ponownie.", "Impossibile verificare il catalogo dell’agente. Riprova."], "No se confirmó el guardado del agente. Revisá las tablas y volvé a cargar su configuración.": ["Agent save was not confirmed. Check the tables and reload its configuration.", "Zapis agenta nie został potwierdzony. Sprawdź tabele i wczytaj konfigurację ponownie.", "Salvataggio dell’agente non confermato. Controlla le tabelle e ricarica la configurazione."]});

Object.assign(DPIA_TRANSLATIONS,{"Carga de puntos sin pago": ["Free point top-up", "Bezpłatne doładowanie punktów", "Ricarica punti gratuita"], "Agregar puntos sin pago": ["Add points for free", "Dodaj punkty bez opłaty", "Aggiungi punti gratuitamente"], "Agregando puntos…": ["Adding points…", "Dodawanie punktów…", "Aggiunta punti…"], "Reintentar recarga": ["Retry top-up", "Ponów doładowanie", "Riprova ricarica"], "Recarga sin pago": ["Free top-up", "Bezpłatne doładowanie", "Ricarica gratuita"], "Historial de puntos": ["Point history", "Historia punktów", "Cronologia punti"], "Seleccioná un paquete para cargar puntos sin pago.": ["Choose a package to add points for free.", "Wybierz pakiet, aby bezpłatnie doładować punkty.", "Scegli un pacchetto per aggiungere punti gratuitamente."], "La recarga suma puntos al saldo compartido. No se realizará ningún pago.": ["The top-up adds points to the shared balance. No payment will be made.", "Doładowanie dodaje punkty do wspólnego salda. Nie zostanie pobrana żadna opłata.", "La ricarica aggiunge punti al saldo condiviso. Non verrà effettuato alcun pagamento."], "No se confirmó la recarga. Reintentá sin cambiar el paquete.": ["Top-up not confirmed. Retry without changing the package.", "Doładowanie nie zostało potwierdzone. Spróbuj ponownie bez zmiany pakietu.", "Ricarica non confermata. Riprova senza cambiare pacchetto."], "Puntos agregados correctamente.": ["Points added successfully.", "Punkty dodano pomyślnie.", "Punti aggiunti correttamente."], "Seleccioná un paquete de 100, 300 u 800 puntos.": ["Select a package of 100, 300 or 800 points.", "Wybierz pakiet 100, 300 lub 800 punktów.", "Seleziona un pacchetto da 100, 300 o 800 punti."], "Solo administradores y usuarios avanzados pueden cargar puntos sin pago.": ["Only administrators and advanced users can add free points.", "Tylko administratorzy i zaawansowani użytkownicy mogą bezpłatnie doładować punkty.", "Solo amministratori e utenti avanzati possono aggiungere punti gratuitamente."], "El identificador de recarga ya está utilizado.": ["The top-up identifier is already in use.", "Identyfikator doładowania jest już używany.", "L’identificativo della ricarica è già utilizzato."], "La cantidad supera el límite del saldo.": ["The amount exceeds the balance limit.", "Kwota przekracza limit salda.", "La quantità supera il limite del saldo."]});

Object.assign(DPIA_TRANSLATIONS,{"Agregar 6 puntos sin pago": ["Add 6 points for free", "Dodaj 6 punktów bez opłaty", "Aggiungi 6 punti gratuitamente"], "Podés agregar 6 puntos por recarga sin realizar un pago.": ["You can add 6 points per top-up without payment.", "Możesz dodawać po 6 punktów bez opłaty.", "Puoi aggiungere 6 punti per ricarica senza pagare."], "La recarga autorizada es de 6 puntos.": ["The authorized top-up is 6 points.", "Dozwolone doładowanie wynosi 6 punktów.", "La ricarica autorizzata è di 6 punti."], "No se confirmó la recarga. Reintentá la misma recarga.": ["Top-up not confirmed. Retry the same top-up.", "Doładowanie nie zostało potwierdzone. Ponów to samo doładowanie.", "Ricarica non confermata. Riprova la stessa ricarica."]});
